fn remove_front(a: &Vec<i32>) -> Vec<i32> {
    // Since `a` is guaranteed to be non-empty, slicing from index 1 to the end
    // is always valid (it will yield an empty slice if `a.len() == 1`).
    a[1..].to_vec()
}

